    INSERT INTO Messages (Code, Texts)
    VALUES
        ('UNEXPECTED_ERROR', N'{"en":"Something went wrong. Please try again.","hi":"कुछ गलत हो गया। कृपया फिर से प्रयास करें।","ar":"حدث خطأ ما. يرجى المحاولة مرة أخرى."}'),
        ('SPEEDTEST_SIZE_INVALID', N'{"en":"The requested size must be between 0 and {0} bytes.","hi":"अनुरोधित आकार 0 से {0} बाइट के बीच होना चाहिए।","ar":"يجب أن يكون الحجم المطلوب بين 0 و {0} بايت."}'),
        ('AUTH_SIGNED_UP', N'{"en":"Your account was created.","hi":"आपका खाता बन गया।","ar":"تم إنشاء حسابك."}'),
        ('AUTH_LOGIN_INVALID', N'{"en":"The e-mail or password is not correct.","hi":"ई-मेल या पासवर्ड सही नहीं है।","ar":"البريد الإلكتروني أو كلمة المرور غير صحيحة."}'),
        ('AUTH_LOCKED', N'{"en":"Too many wrong tries. Try again in {0} minutes.","hi":"बहुत सारी गलत कोशिशें। {0} मिनट बाद फिर कोशिश करें।","ar":"محاولات خاطئة كثيرة. حاول مرة أخرى بعد {0} دقيقة."}'),
        ('AUTH_EMAIL_INVALID', N'{"en":"Enter a valid e-mail address.","hi":"मान्य ई-मेल पता दर्ज करें।","ar":"أدخل عنوان بريد إلكتروني صالحًا."}'),
        ('AUTH_EMAIL_TAKEN', N'{"en":"An account with this e-mail already exists. Log in instead.","hi":"इस ई-मेल से पहले से एक खाता है। इसके बजाय लॉग इन करें।","ar":"يوجد حساب بهذا البريد الإلكتروني بالفعل. سجّل الدخول بدلًا من ذلك."}'),
        ('AUTH_PASSWORD_WEAK', N'{"en":"The password must be at least {0} characters long.","hi":"पासवर्ड कम से कम {0} अक्षरों का होना चाहिए।","ar":"يجب ألا تقل كلمة المرور عن {0} أحرف."}'),
        ('AUTH_PASSWORD_WRONG', N'{"en":"The current password is not correct.","hi":"मौजूदा पासवर्ड सही नहीं है।","ar":"كلمة المرور الحالية غير صحيحة."}'),
        ('AUTH_PASSWORD_CHANGED', N'{"en":"Your password was changed. Other devices have been logged out.","hi":"आपका पासवर्ड बदल दिया गया। दूसरे डिवाइस से लॉग आउट कर दिया गया है।","ar":"تم تغيير كلمة المرور. تم تسجيل الخروج من الأجهزة الأخرى."}'),
        ('AUTH_PROFILE_SAVED', N'{"en":"Your profile was saved.","hi":"आपकी प्रोफ़ाइल सहेज ली गई।","ar":"تم حفظ ملفك الشخصي."}'),
        ('AUTH_PROFILE_INVALID', N'{"en":"Enter a name of up to {0} characters and choose a language.","hi":"{0} अक्षरों तक का नाम दर्ज करें और भाषा चुनें।","ar":"أدخل اسمًا لا يزيد عن {0} حرفًا واختر لغة."}'),
        ('AUTH_SESSION_INVALID', N'{"en":"Your session has ended. Please log in again.","hi":"आपका सत्र समाप्त हो गया। कृपया फिर से लॉग इन करें।","ar":"انتهت جلستك. يرجى تسجيل الدخول مرة أخرى."}'),
        ('AUTH_LOGGED_OUT', N'{"en":"You have been logged out.","hi":"आप लॉग आउट हो गए हैं।","ar":"تم تسجيل خروجك."}'),
        ('AUTH_FORBIDDEN', N'{"en":"You do not have access to this. Ask an administrator to give you access.","hi":"आपके पास इसकी पहुँच नहीं है। किसी एडमिन से पहुँच देने के लिए कहें।","ar":"ليس لديك صلاحية الوصول إلى هذا. اطلب من المسؤول منحك الصلاحية."}'),
        ('AUTH_USER_NOT_FOUND', N'{"en":"This user was not found.","hi":"यह उपयोगकर्ता नहीं मिला।","ar":"لم يتم العثور على هذا المستخدم."}'),
        ('AUTH_APP_UNKNOWN', N'{"en":"The app \"{0}\" does not exist.","hi":"ऐप \"{0}\" मौजूद नहीं है।","ar":"التطبيق \"{0}\" غير موجود."}'),
        ('AUTH_LAST_ADMIN', N'{"en":"At least one administrator must remain.","hi":"कम से कम एक एडमिन रहना चाहिए।","ar":"يجب أن يبقى مسؤول واحد على الأقل."}'),
        ('AUTH_ACCESS_SAVED', N'{"en":"Access was saved.","hi":"पहुँच सहेज ली गई।","ar":"تم حفظ الصلاحيات."}'),
        ('MUSIC_PLAYER_NOT_FOUND', N'{"en":"This player was not found.","hi":"यह प्लेयर नहीं मिला।","ar":"لم يتم العثور على هذا المشغل."}'),
        ('MUSIC_TRACK_NOT_FOUND', N'{"en":"This track was not found.","hi":"यह ट्रैक नहीं मिला।","ar":"لم يتم العثور على هذا المقطع."}'),
        ('MUSIC_FILE_TYPE_INVALID', N'{"en":"The file type {0} is not supported.","hi":"फ़ाइल प्रकार {0} समर्थित नहीं है।","ar":"نوع الملف {0} غير مدعوم."}'),
        ('MUSIC_NO_FILES', N'{"en":"Choose at least one audio file.","hi":"कम से कम एक ऑडियो फ़ाइल चुनें।","ar":"اختر ملف صوت واحدًا على الأقل."}'),
        ('MUSIC_FILE_MISSING', N'{"en":"The audio file is missing on the server.","hi":"ऑडियो फ़ाइल सर्वर पर उपलब्ध नहीं है।","ar":"ملف الصوت غير موجود على الخادم."}'),
        ('MUSIC_TRACKS_UPLOADED', N'{"en":"{0} track(s) added.","hi":"{0} ट्रैक जोड़े गए।","ar":"تمت إضافة {0} مقطع."}'),
        ('MUSIC_TRACK_DELETED', N'{"en":"The track was deleted.","hi":"ट्रैक हटा दिया गया।","ar":"تم حذف المقطع."}'),
        ('YOUTUBE_QUERY_REQUIRED', N'{"en":"Enter a search text.","hi":"खोजने के लिए कुछ लिखें।","ar":"أدخل نص البحث."}'),
        ('YOUTUBE_VIDEO_ID_INVALID', N'{"en":"This is not a valid video id.","hi":"यह मान्य वीडियो आईडी नहीं है।","ar":"معرّف الفيديو غير صالح."}'),
        ('YOUTUBE_PLAYLIST_ID_INVALID', N'{"en":"This is not a valid playlist id.","hi":"यह मान्य प्लेलिस्ट आईडी नहीं है।","ar":"معرّف قائمة التشغيل غير صالح."}'),
        ('YOUTUBE_LOOKUP_FAILED', N'{"en":"YouTube could not be reached for this request.","hi":"इस अनुरोध के लिए YouTube से संपर्क नहीं हो सका।","ar":"تعذر الوصول إلى يوتيوب لهذا الطلب."}'),
        ('YOUTUBE_NO_AUDIO', N'{"en":"No audio stream is available for this video.","hi":"इस वीडियो के लिए कोई ऑडियो स्ट्रीम उपलब्ध नहीं है।","ar":"لا يتوفر مسار صوتي لهذا الفيديو."}'),
        ('TRANSLATION_LANGUAGE_INVALID', N'{"en":"This language is not supported.","hi":"यह भाषा समर्थित नहीं है।","ar":"هذه اللغة غير مدعومة."}'),
        ('TOO_MANY_REQUESTS', N'{"en":"Too many attempts. Please wait a few minutes and try again.","hi":"बहुत अधिक प्रयास। कृपया कुछ मिनट प्रतीक्षा करें और फिर प्रयास करें।","ar":"محاولات كثيرة جدًا. يرجى الانتظار بضع دقائق ثم المحاولة مرة أخرى."}'),
        ('YOUTUBE_FFMPEG_MISSING', N'{"en":"MP3 conversion is not available on this server.","hi":"इस सर्वर पर MP3 रूपांतरण उपलब्ध नहीं है।","ar":"تحويل MP3 غير متاح على هذا الخادم."}'),
        ('YOUTUBE_KEY_SAVED', N'{"en":"The YouTube API key was saved.","hi":"YouTube API कुंजी सहेज ली गई।","ar":"تم حفظ مفتاح YouTube API."}'),
        ('YOUTUBE_KEY_REJECTED', N'{"en":"YouTube did not accept this API key. Check the key and that the YouTube Data API v3 is enabled for it.","hi":"YouTube ने यह API कुंजी स्वीकार नहीं की। कुंजी जाँचें और देखें कि उसके लिए YouTube Data API v3 चालू है।","ar":"لم يقبل YouTube مفتاح API هذا. تحقق من المفتاح ومن تفعيل YouTube Data API v3 له."}'),
        ('SETTINGS_SAVED', N'{"en":"Settings saved.","hi":"सेटिंग्स सहेजी गईं।","ar":"تم حفظ الإعدادات."}'),
        ('SETTINGS_INVALID', N'{"en":"Some of the settings are not valid.","hi":"कुछ सेटिंग्स मान्य नहीं हैं।","ar":"بعض الإعدادات غير صالحة."}'),
        ('KHATA_BOOK_NOT_FOUND', N'{"en":"This book was not found.","hi":"यह खाता-बही नहीं मिली।","ar":"لم يتم العثور على هذا الدفتر."}'),
        ('KHATA_BOOK_NAME_INVALID', N'{"en":"Enter a book name of up to {0} characters.","hi":"अधिकतम {0} अक्षरों का बही का नाम दर्ज करें।","ar":"أدخل اسم دفتر لا يزيد عن {0} حرفًا."}'),
        ('KHATA_BOOK_NAME_TAKEN', N'{"en":"You already have a book with this name.","hi":"इस नाम की बही आपके पास पहले से है।","ar":"لديك بالفعل دفتر بهذا الاسم."}'),
        ('KHATA_BOOK_CURRENCY_LOCKED', N'{"en":"The money type of a book can''t be changed after its first entry.","hi":"पहली एंट्री के बाद बही की मुद्रा नहीं बदली जा सकती।","ar":"لا يمكن تغيير عملة الدفتر بعد أول قيد فيه."}'),
        ('KHATA_BOOK_DELETED', N'{"en":"The book has been deleted.","hi":"बही हटा दी गई है।","ar":"تم حذف الدفتر."}'),
        ('KHATA_BOOK_LIMIT', N'{"en":"You can have up to {0} books.","hi":"आप अधिकतम {0} बही रख सकते हैं।","ar":"يمكنك امتلاك {0} دفاتر كحد أقصى."}'),
        ('KHATA_CURRENCY_LIMIT', N'{"en":"You can add up to {0} money types of your own.","hi":"आप अधिकतम {0} अपनी मुद्राएँ जोड़ सकते हैं।","ar":"يمكنك إضافة {0} عملات خاصة بك كحد أقصى."}'),
        ('KHATA_CONTACT_LIMIT', N'{"en":"A book can have up to {0} contacts.","hi":"एक बही में अधिकतम {0} संपर्क हो सकते हैं।","ar":"يمكن أن يحتوي الدفتر على {0} جهة اتصال كحد أقصى."}'),
        ('KHATA_CURRENCY_NOT_FOUND', N'{"en":"This money type was not found.","hi":"यह मुद्रा नहीं मिली।","ar":"لم يتم العثور على هذه العملة."}'),
        ('KHATA_CURRENCY_INVALID', N'{"en":"Enter a code and a symbol of up to 10 characters, a name of up to 50 characters, and 0 to 3 decimals.","hi":"अधिकतम 10 अक्षरों का कोड और चिह्न, अधिकतम 50 अक्षरों का नाम और 0 से 3 दशमलव दर्ज करें।","ar":"أدخل رمزًا ورمز عرض لا يزيد كل منهما عن 10 أحرف، واسمًا لا يزيد عن 50 حرفًا، ومن 0 إلى 3 خانات عشرية."}'),
        ('KHATA_CURRENCY_CODE_TAKEN', N'{"en":"A money type with this code already exists.","hi":"इस कोड की मुद्रा पहले से मौजूद है।","ar":"توجد عملة بهذا الرمز بالفعل."}'),
        ('KHATA_CURRENCY_IN_USE', N'{"en":"This money type is used by a book, so its code and decimals can''t change and it can''t be removed.","hi":"यह मुद्रा किसी बही में उपयोग हो रही है, इसलिए इसका कोड और दशमलव नहीं बदले जा सकते और इसे हटाया नहीं जा सकता।","ar":"هذه العملة مستخدمة في دفتر، لذا لا يمكن تغيير رمزها وخاناتها العشرية ولا حذفها."}'),
        ('KHATA_CURRENCY_DELETED', N'{"en":"The money type has been removed.","hi":"मुद्रा हटा दी गई है।","ar":"تمت إزالة العملة."}'),
        ('KHATA_CONTACT_NOT_FOUND', N'{"en":"This contact was not found.","hi":"यह संपर्क नहीं मिला।","ar":"لم يتم العثور على جهة الاتصال هذه."}'),
        ('KHATA_CONTACT_INVALID', N'{"en":"Enter a name of up to 100 characters. A mobile number or email, if given, must be valid.","hi":"अधिकतम 100 अक्षरों का नाम दर्ज करें। मोबाइल नंबर या ईमेल देने पर वह मान्य होना चाहिए।","ar":"أدخل اسمًا لا يزيد عن 100 حرف. يجب أن يكون رقم الجوال أو البريد الإلكتروني صالحًا إذا أدخلته."}'),
        ('KHATA_CONTACT_DELETED', N'{"en":"The contact has been deleted.","hi":"संपर्क हटा दिया गया है।","ar":"تم حذف جهة الاتصال."}'),
        ('KHATA_ENTRY_NOT_FOUND', N'{"en":"This entry was not found.","hi":"यह एंट्री नहीं मिली।","ar":"لم يتم العثور على هذا القيد."}'),
        ('KHATA_ENTRY_INVALID', N'{"en":"Enter an amount above zero, a valid date and a note of up to 500 characters.","hi":"शून्य से अधिक राशि, मान्य तारीख और अधिकतम 500 अक्षरों का नोट दर्ज करें।","ar":"أدخل مبلغًا أكبر من صفر وتاريخًا صالحًا وملاحظة لا تزيد عن 500 حرف."}'),
        ('KHATA_ENTRY_NOT_YOURS', N'{"en":"You can only change entries you added.","hi":"आप केवल अपनी जोड़ी हुई एंट्री ही बदल सकते हैं।","ar":"يمكنك تعديل القيود التي أضفتها أنت فقط."}'),
        ('KHATA_ENTRY_DELETED', N'{"en":"The entry has been deleted.","hi":"एंट्री हटा दी गई है।","ar":"تم حذف القيد."}'),
        ('KHATA_CHANGED_ELSEWHERE', N'{"en":"This was changed by someone else. Reload and try again.","hi":"इसे किसी और ने बदल दिया है। फिर से लोड करें और दोबारा प्रयास करें।","ar":"قام شخص آخر بتغيير هذا. أعد التحميل وحاول مرة أخرى."}'),
        ('KHATA_REQUEST_IN_PROGRESS', N'{"en":"This request is already being processed.","hi":"यह अनुरोध पहले से प्रोसेस हो रहा है।","ar":"هذا الطلب قيد المعالجة بالفعل."}'),
        ('KHATA_REQUEST_KEY_REUSED', N'{"en":"This request key was already used for a different request.","hi":"यह अनुरोध कुंजी किसी दूसरे अनुरोध के लिए पहले ही उपयोग हो चुकी है।","ar":"تم استخدام مفتاح الطلب هذا بالفعل لطلب مختلف."}');
